// The torsion spring: a kinetic block that turns its output shaft by a set
// angle, then stops. It is the mechanical version of the steering wheel.
//
// The block entity is a pass-through shaft; the actual rotation is generated by
// an "output" sub-entity (`Output` in Java) that borrows the same block. The
// output turns while the parent turns, holds the angle while the parent stops,
// and winds back to zero when the parent stops and the block is unpowered.
//
// Pure: no host imports.
//
// Java: dev.simulated_team.simulated.content.blocks.torsion_spring.TorsionSpringBlockEntity
// create/sable internals are not exported from their barrels yet.
// ignore_for_file: implementation_imports

import 'dart:math' as math;

import 'package:create/src/kinetics/settings.dart' show convertToAngular;

/// The state of the output of a torsion spring.
enum TorsionOutputState { stopped, turning }

/// The output shaft of a torsion spring.
final class TorsionSpringOutputLogic {
  /// The angle the output is at, in degrees.
  double angle = 0;

  /// The angle at the start of this tick (for interpolation).
  double oldAngle = 0;

  /// The angle the output is turning to.
  double targetAngle = 0;

  /// The last non-zero spring input speed.
  double lastSpringSpeed = 0;

  /// The speed the output reports.
  double generatedSpeed = 0;

  /// The speed queued for the next tick.
  double queuedSpeed = 0;

  /// The angular distance the current turn may still cover.
  double sequencedAngleLimit = -1;

  /// Set when a tick wound a stopped output back to zero, the `REWIND_TIME`
  /// event (`TorsionSpringBlockEntity.java:252`). The block entity reads it after
  /// [tick] and awards the advancement; the logic itself has no world.
  bool rewoundToZero = false;

  int rotationDurationTicks = 0;
  int rotationProgressTicks = 0;

  TorsionOutputState state = TorsionOutputState.stopped;

  /// Whether the output is static (the angle did not change last tick).
  bool get isStatic => angle == oldAngle;

  /// `interpolatedSpring(pt)`.
  double interpolated(double partialTick) =>
      oldAngle + (angle - oldAngle) * partialTick;

  /// One tick of the output.
  ///
  /// [parentSpeed] is the speed of the pass-through shaft, [angleLimit] the value
  /// from the block's value box, [powered] the redstone state, and [speed] the
  /// speed the output is being driven at.
  ///
  /// Returns true when the output stopped this tick (the network needs an
  /// update).
  bool tick({
    required double parentSpeed,
    required double angleLimit,
    required bool powered,
    required double speed,
  }) {
    oldAngle = angle;
    generatedSpeed = queuedSpeed;

    // Remember the speed the parent turns at: the output keeps it while it
    // holds its angle, so the wind-back can use it once the parent stops.
    if (parentSpeed != 0) lastSpringSpeed = parentSpeed;

    var stopped = false;

    if (rotationDurationTicks >= 0 &&
        rotationProgressTicks <= rotationDurationTicks) {
      rotationProgressTicks++;

      var angularSpeed = convertToAngular(speed);
      if (sequencedAngleLimit >= 0) {
        angularSpeed = angularSpeed.clamp(-sequencedAngleLimit, sequencedAngleLimit);
        sequencedAngleLimit = math.max(0, sequencedAngleLimit - angularSpeed.abs());
      }

      angle += angularSpeed;

      if (rotationProgressTicks == rotationDurationTicks) {
        rotationProgressTicks = -1;
        rotationDurationTicks = -1;
        queuedSpeed = 0;
        state = TorsionOutputState.stopped;
        stopped = true;
      }
    }

    final parentStopped = parentSpeed == 0;

    if (state == TorsionOutputState.turning && parentStopped) {
      if (targetAngle != 0 || powered) stopTurning();
    } else if (state == TorsionOutputState.stopped && parentStopped && !powered) {
      // Unpowered and stopped: wind back to zero.
      if (targetAngle != 0) {
        beginTurnTo(0);
        rewoundToZero = true;
      }
    } else if (state == TorsionOutputState.turning) {
      // A direction change on the parent stops the turn, so the next tick starts
      // a new one towards the new target.
      final target = angleLimit * parentSpeed.sign;
      if (targetAngle != target || lastSpringSpeed != generatedSpeed) stopTurning();
    } else if (!parentStopped && state == TorsionOutputState.stopped) {
      beginTurnTo(angleLimit * parentSpeed.sign);
    }

    return stopped;
  }

  /// `stopTurning()`.
  void stopTurning() {
    rotationProgressTicks = -1;
    rotationDurationTicks = -1;
    sequencedAngleLimit = -1;
    targetAngle = double.maxFinite;
    queuedSpeed = 0;
    state = TorsionOutputState.stopped;
  }

  /// `beginTurnTo(target)`: start turning towards [target].
  ///
  /// [parentSequencedLimit] is the parent's sequenced angle limit (a negative
  /// value means "none").
  void beginTurnTo(double target, {double parentSequencedLimit = -1}) {
    var relativeAngle = target - angle;
    if (relativeAngle == 0) return;
    if (state == TorsionOutputState.turning && targetAngle == target) return;

    // A fresh output has no remembered speed yet; a single RPM is enough to
    // compute a duration, and the first tick with a parent speed replaces it.
    final baseSpeed = lastSpringSpeed == 0 ? 1.0 : lastSpringSpeed.abs();
    lastSpringSpeed = baseSpeed * relativeAngle.sign;

    if (parentSequencedLimit >= 0) {
      relativeAngle = relativeAngle.clamp(-parentSequencedLimit, parentSequencedLimit);
    }

    targetAngle = target;

    final degreesPerTick = convertToAngular(lastSpringSpeed.abs());
    if (degreesPerTick == 0) return;

    rotationDurationTicks = (relativeAngle.abs() / degreesPerTick).ceil() + 2;
    rotationProgressTicks = 0;
    sequencedAngleLimit = relativeAngle.abs();
    state = TorsionOutputState.turning;
    queuedSpeed = lastSpringSpeed;
    generatedSpeed = queuedSpeed;
  }

  /// `onSpeedChanged(previousSpeed, newSpeed)`: keeps the last non-zero speed.
  void updateParentSpeed(double previousSpeed, double newSpeed) {
    if (newSpeed != 0) {
      lastSpringSpeed = newSpeed;
    } else if (previousSpeed != 0) {
      lastSpringSpeed = previousSpeed;
    }
  }

  /// `write()`.
  Map<String, Object?> write() => {
    'OldAngle': oldAngle,
    'Angle': angle,
    'TargetAngle': targetAngle,
    'LastSpringSpeed': lastSpringSpeed,
    'CurrentState': state.index,
    'RotationProgressTicks': rotationProgressTicks,
    'RotationDurationTicks': rotationDurationTicks,
    'GeneratedSpeed': generatedSpeed,
    'QueuedSpeed': queuedSpeed,
    if (sequencedAngleLimit >= 0) 'SequencedAngleLimit': sequencedAngleLimit,
  };

  /// `read()`.
  void read(Map<String, Object?> tag) {
    oldAngle = _double(tag['OldAngle']);
    angle = _double(tag['Angle']);
    targetAngle = _double(tag['TargetAngle']);
    lastSpringSpeed = _double(tag['LastSpringSpeed']);
    sequencedAngleLimit = tag.containsKey('SequencedAngleLimit')
        ? _double(tag['SequencedAngleLimit'])
        : -1;
    rotationProgressTicks = _int(tag['RotationProgressTicks']);
    rotationDurationTicks = _int(tag['RotationDurationTicks']);
    generatedSpeed = _double(tag['GeneratedSpeed']);
    queuedSpeed = _double(tag['QueuedSpeed']);
    final index = _int(tag['CurrentState']);
    state = index >= 0 && index < TorsionOutputState.values.length
        ? TorsionOutputState.values[index]
        : TorsionOutputState.stopped;
  }

  static double _double(Object? value) => value is num ? value.toDouble() : 0;

  static int _int(Object? value) => value is num ? value.toInt() : 0;
}

/// The comparator output of the torsion spring (`getAnalogOutputSignalFrom`).
int torsionSpringAnalogOutput({
  required double angle,
  required double angleLimit,
  required String facingName,
  required String sideName,
}) {
  if (angle.abs() < 0.99) return 0;

  final frac = (angle / angleLimit).clamp(-1.0, 1.0);
  final positive = facingName == 'east' || facingName == 'south';
  final value = (frac < 0 ? (frac * 15).floor() : (frac * 15).ceil()) * (positive ? -1 : 1);

  final clockwise = switch (facingName) {
    'north' => 'east',
    'east' => 'south',
    'south' => 'west',
    'west' => 'north',
    _ => '',
  };
  final counterClockwise = switch (facingName) {
    'north' => 'west',
    'west' => 'south',
    'south' => 'east',
    'east' => 'north',
    _ => '',
  };

  if (clockwise == sideName && value > 0) return value;
  if (counterClockwise == sideName && value < 0) return -value;
  return 0;
}
